func lifecycleArmFor(alias string) []*regexp.Regexp {
  pred := `\s*(=\s*'active'|IN\s*\('active'|NOT\s+IN\s*\('deleted')`
  if alias == "" { return []*regexp.Regexp{ regexp.MustCompile(`(^|[^.\w])status`+pred), ... } }  // [^.\w] stops sni.status matching; RE2 has no lookbehind
  return []*regexp.Regexp{ regexp.MustCompile(`\b`+q+`\.status`+pred), regexp.MustCompile(`PageWantedLivePredicateFor\s*\(\s*"`+q+`"\s*\)`) }
}

